const items = $('Split Forget Keys').all();

const labels = {
  "*": "всё, что знал о тебе",

  name: "имя",
  age: "возраст",
  city: "город",

  spouse: "имя жены",

  pet_name: "имя питомца",
  pet_type: "тип питомца",
  pet_color: "цвет питомца",

  diabetes_type: "диабет первого типа",
  diabetes_duration_years: "стаж диабета",

  hobby: "хобби",
  hobby_2: "второе хобби",
  hobby_3: "третье хобби"
};

const deleted = items.map(item => {
  const key = item.json.memory_key;
  return labels[key] ?? key;
});

let reply;

if (deleted.includes("всё, что знал о тебе")) {
  reply = "Хорошо. Я забыл всё, что знал о тебе.";
} else if (deleted.length === 1) {
  reply = `Хорошо. Я забыл ${deleted[0]}.`;
} else {
  reply = `Хорошо. Я забыл: ${deleted.join(", ")}.`;
}

return [
  {
    json: {
      reply
    }
  }
];

const m = $json["output.memories"];

const norm = (v) => String(v ?? "").trim();

const memory = {
  category: norm(m.category),
  owner: norm(m.owner || "self").toLowerCase(),

  ontology_id: Number($json.out_ontology_id),

  memory_key: norm(
    $json.out_canonical_key
  ).toLowerCase(),

  memory_value: norm(m.memory_value),

  confidence: Number(m.confidence ?? 0.99)
};

memory.memory_text =
  `${memory.owner} | ${memory.memory_key}: ${memory.memory_value}`;

return memory;

const memory = $("Prepare Memory").item.json;
const embedding = $json.data[0].embedding;

return {
  user_id: $("Input Gateway").item.json.chat.id,

  category: memory.category,
  owner: memory.owner,

  memory_key: memory.memory_key,
  memory_value: memory.memory_value,

  memory_text: memory.memory_text,

  confidence: memory.confidence,

  embedding: JSON.stringify(embedding)
};

const unique=new Map();
for(const item of $input.all()){
 const j=item.json;
 const id=`${j.owner||'self'}|${j.memory_key}|${j.memory_value}`;
 const prev=unique.get(id);
 if(!prev || (j.distance??999)<(prev.json.distance??999)) unique.set(id,item);
}
return [...unique.values()]
.sort((a,b)=>(a.json.distance??0)-(b.json.distance??0))
.slice(0,20);

const memories = $input.all();
const q = $('Input Gateway').item.json.message.text.toLowerCase();

if (memories.length === 0) {
  return [];
}

// Показываем всю память по специальным запросам
const showAll = [
  "что ты обо мне знаешь",
  "что ты помнишь",
  "покажи память",
  "мой профиль",
  "моя память"
];

if (showAll.some(x => q.includes(x))) {
  return memories;
}

// -------------------------------------------------
// Удаляем дубликаты
// -------------------------------------------------

const unique = new Map();

for (const item of memories) {
  const m = item.json;

  const id = `${m.owner ?? "self"}|${m.memory_key}|${m.memory_value}`;

  const prev = unique.get(id);

  if (
    !prev ||
    (m.distance ?? 999) < (prev.json.distance ?? 999)
  ) {
    unique.set(id, item);
  }
}

const list = [...unique.values()];

// -------------------------------------------------
// Сортировка
// -------------------------------------------------

list.sort((a, b) => {
  const da = a.json.distance ?? 999;
  const db = b.json.distance ?? 999;
  return da - db;
});

// -------------------------------------------------
// Если есть действительно близкие совпадения,
// возвращаем только их.
// Иначе возвращаем весь список,
// чтобы AI сам выбрал нужный факт.
// -------------------------------------------------

const relevant = list.filter(i => (i.json.distance ?? 999) <= 0.90);

return relevant.length > 0 ? relevant : list;

// =========================================
// JARVIS Intent Classifier v1
// =========================================

const input = $input.first().json;

const text = (input.message?.text ?? "")
  .trim()
  .toLowerCase();

let intent = "chat";
let confidence = 1.0;

// -------------------------
// Forget Memory
// -------------------------

const forgetPatterns = [
  "забудь",
  "забыть",
  "забудьте",
  "удали память",
  "удалить память",
  "очисти память",
  "сотри память",
  "forget"
];

if (forgetPatterns.some(p => text.includes(p))) {
  intent = "forget_memory";
}

// -------------------------
// Recall Memory
// -------------------------

else {

  const recallPatterns = [
    "что ты обо мне помнишь",
    "что ты помнишь обо мне",
    "что ты знаешь обо мне",
    "моя память",
    "мой профиль",
    "покажи память",
    "что обо мне известно"
  ];

  if (recallPatterns.some(p => text.includes(p))) {
    intent = "recall_memory";
  }

}

// -------------------------
// Result
// -------------------------

return [{
  json: {
    ...input,
    intent,
    confidence
  }
}];
